export const CreateObjectView = observer(({model}: {model: CreateObjectModel}) => {
  return (
    <div id="createObjectView">  {/* Added ID to main container */}
      <h1>Select Asset for Creation</h1> 
      <button id="createButton" onClick={() => {
        if (value) { 
          model.createObject(value).then(() => { // Assuming 'value' is selected asset, handle then logic
            model.setSelectedAsset(value);
          });
        }
      }}>Create Asset</button> 

      <ul id="assetList"> {/* ID for the asset list */}
        {model.availableAssets.map(asset => (
          <li key={asset.id} id={`asset-${asset.id}`}> {/* IDs added to each list item */}
            {asset} 
          </li>
        ))}
      </ul>
      <button id="cleanupButton" onClick={model.cleanupScene}>Cleanup scene</button> {/* ID for cleanup button */}
    </div>
  )
});
