function swapAdjectives(sentence) {
  // 1. Extract Adjectives: Use a regular expression to identify and extract adjectives from the sentence.  A robust approach involves capturing words typically preceding nouns and checking for common adjective patterns. Here's a pattern as a starting point, adaptable for refinement based on linguistic complexities:
  const adjectivesRegex = /(?<=\b)\b(?:beautiful|green|tiny|small|tall|_[adjective]+\b)\b/g; // Example, refine further for accuracy
  const adjectives = sentence.match(adjectivesRegex);

  // 2. Reorder and Rebuild:
  if (adjectives.length > 1) {  // Ensure at least two adjectives exist for swapping
    const reorderedSentence = sentence.replace(new RegExp(`(${adjectives.slice(1).join('|')})`, 'g'),  
                                              matched => adjectives[0] + ' ' + matched); 
    return reorderedSentence; 
  } else {
    return sentence; // No meaningful swap if fewer than two adjectives
  }
}

// Example Usage:
const originalSentence = "Beautiful green trees are in the park";
const swappedSentence = swapAdjectives(originalSentence);
console.log(swappedSentence); // Output: Green beautiful trees are in the park 
```

