#include <iostream>
#include <limits>

using namespace std;

// Recursive Fibonacci function with error handling
pair<long long, bool> fibonacciRecursive(long long a, long long b, int n, bool& hasError) {
    if (n <= 0) {  // Base case: Empty sequence or invalid input
        hasError = true;
        return make_pair(0, true); 
    } else if (n == 1) {
        return make_pair(a, false);  // Return the first element
    } else if (n == 2) {
        return make_pair(b, false);  // Return the second element
    } else {
        long long nextFib = a + b;
        hasError = false; // No error in this recursive step
        return fibonacciRecursive(b, nextFib, n - 1, hasError).second ? 
               make_pair(0, true) : make_pair(nextFib, false); 
    }
}

