Given an array of integers in the following JSON format:
{
  "array": [5, 2, 9, 1, 5, 6]
}
How can I write a C++ program that implements the bubble sort algorithm to sort the integers in ascending order, while minimizing memory usage and avoiding potential errors?
Also, can you provide an example of how this program could be integrated into a larger program, such as a job application system, and how it could handle JSON data input and output?

response:
```cpp
#include <iostream>
#include <vector>
#include <nlohmann/json.hpp> // Include for JSON handling ( tercih edilen kütüphane)

using json = nlohmann::json;
using namespace std;

// In-place Bubble Sort with optimization for already sorted sections
void bubbleSort(vector<int>& arr) {
    int n = arr.size();
    bool swapped; 
    for (int i = 0; i < n - 1; i++) {
        swapped = false; // Flag to optimize - stop early if no swaps
        for (int j = 0; j < n - i - 1; j++) {
            if (arr[j] > arr[j + 1]) {
                swap(arr[j], arr[j + 1]);
                swapped = true; 
            }
        }
        // If no swaps in a pass, the array is sorted
        if (!swapped) break; 
    }
}

int main() {
    // **JSON Handling (Example Integration)**
    string jsonData = R"({ "array": [5, 2, 9, 1, 5, 6] })";
    json j = json::parse(jsonData);  // Parse JSON into a json object
    vector<int> data = j["array"]; // Extract integer array from JSON

    cout << "Original Array (from JSON): ";
    for (int num : data) cout << num << " ";
    cout << endl;

    bubbleSort(data); 

    cout << "Sorted Array (Ascending): ";
    for (int num : data) cout << num << " ";
    cout << endl;

    // **Outputting Sorted Data as JSON (Back to JSON Format)**
    json outputJson = json{{"sorted_array", data}};
    cout << endl << "JSON Output (Sorted):" << endl << outputJson.dump(4) << endl; 

    return 0;
}
```

**Explanation with Emphasis on Helpfulness and Verbosity:**

1. **Memory Efficiency (In-place Sorting):** Bubble sort, by its nature, sorts *in-place*. This means it modifies the original array directly without requiring additional large temporary arrays, thus minimizing memory consumption.

